    """Validates a given date string and returns True if the date is valid otherwise False."""

    # Check if the date string is not empty
    if not date:
        return False

    # Split the date string into components
    month, day, year = date.split('-')

    # Check if the date is in the correct format (mm-dd-yyyy)
    if len(date) != 10 or date[2] != '-' or date[5] != '-':
        return False

    # Convert the month and day to integers
    try:
        month = int(month)
        day = int(day)
        year = int(year)
    except ValueError:
        return False

    # Check if the month is between 1 and 12
    if month < 1 or month > 12:
        return False

    # Check if the day is between 1 and 31 for months 1, 3, 5, 7, 8, 10, 12
    if month in [1, 3, 5, 7, 8, 10, 12]:
        if day < 1 or day > 31:
            return False
    # Check if the day is between 1 and 30 for months 4, 6, 9, 11
    elif month in [4, 6, 9, 11]:
        if day < 1 or day > 30:
            return False
    # Check if the day is between 1 and 29 for month 2
    elif month == 2:
        # Check if the year is a leap year
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            if day < 1 or day > 29:
                return False
        else:
            if day < 1 or day > 28:
                return False

    return True
